$(function() {
    $(".table-cart").DataTable({
        scrollY:        300,
        scrollX:        true,
        scrollCollapse: true,
        paging:         false,
        searching: false,
        info: false,
        ordering: false
    });


    $(document).on("change keyup", ".table-cart select, .table-cart input", function (e) {
        //setSiblingRequired();
        setRequired($(this));
    });

    $(document).on("change keyup", ".grid-raw select, .grid-raw input", function (e) {
        rollBackOnDuplicate($(this));
        calculateShrimpRaw();
    });

    $(document).on("change keyup", ".grid-block select, .grid-block input", function (e) {
        rollBackOnDuplicate($(this));
        calculateShrimpBlock();
    });

    $(document).on("change keyup", ".grid-carton select, .grid-carton input", function (e) {
        rollBackOnDuplicate($(this));
        calculateShrimpCarton();
    });


    $(document).on("change keyup", "#isaveragerate, #averagerate", function (e) {
        setRateClass();
    });


});

function setRateClass(){
    if($('#isaveragerate').length > 0) {
        var robj, val, dataval;
        if ($('#isaveragerate').is(":checked")) {
            var averagerate = $('#averagerate').val();
            $('#averagerate').prop('required', true);
            $('#averagerate').prop('readonly',false);
            $( 'table.table-cart tbody tr .rate' ).each(function() {
                robj = $(this);
                robj.prop('readonly',true);
                val = robj.val();
                //dataval = (robj.attr('data-val'))?robj.attr('data-val'):'0';
                if(!robj.attr('data-val')){
                    dataval = robj.attr('data-val');
                    robj.attr('data-val',val);
                }
                robj.val(averagerate);
                robj.hide();
            });
        } else {
            $('#averagerate').prop('required', false);
            $('#averagerate').prop('readonly',true);
            $( 'table.table-cart tbody tr .rate' ).each(function() {
                robj = $(this);
                robj.prop('readonly',false);
                dataval = robj.attr('data-val');
                robj.val(dataval);
                robj.removeAttr('data-val');
                robj.show();
            });
        }

        if($('.grid-raw').length > 0){
            calculateShrimpRaw();
        } else if($('.grid-block').length > 0){
            calculateShrimpBlock();
        } else if($('.grid-carton').length > 0){
            calculateShrimpCarton();
        }
        //setSiblingRequired();
        setRequired($(this));
    }
}

function setSiblingRequired()
{
    var tr, obj, value;
    $( 'table.table-cart tbody tr' ).each(function() {
        tr = $(this);
        //tr.find('.requireable').removeAttr('isrequired');
        tr.find('input[type=number].requireable').prop('min',0);
        tr.find( 'select, input[type=number]:not([readonly])' ).each(function() {
            value = $(this).val();
            if(value != '0' && value != '' && value != 'CARTON'){
                tr.find('.requireable').prop('required',true);
                tr.find('input[type=number].requireable').prop('min',1);
            }
        })
    });
}


function calculateShrimpRaw()
{
    var tr, rate = kg = price = totalkg = totalprice = 0;
    $( 'table.grid-raw tbody tr' ).each(function() {
        tr = $(this);
        rate = parseFloat(tr.find('.rate').val());
        kg = parseFloat(tr.find('.kg').val());
        if(isNumber(rate) && isNumber(kg)){
            price = getDecimal((rate * kg), 2);
            tr.find('.price').val(price);
            totalprice += price;
            totalkg += kg;
        }
    });


    $( 'table.grid-raw #totalkg' ).html(bdt_format(totalkg,3));
    $( 'table.grid-raw #totalprice' ).html(bdt_format(totalprice,2));
}

function getRate(obj){
    if($('#isaveragerate').length > 0) {
        if ($('#isaveragerate').is(":checked")) {
            return $('#isaveragerate').val();
        }
    }
    return obj.val();
}

function calculateShrimpCarton()
{
    var cartonid, carton, tr, ratetype, rate = kg = inkg = qty = price = totalkg = totalprice = totalqty = 0;

    $( 'table.grid-carton tbody tr' ).each(function() {
        tr = $(this);
        rate = parseFloat(tr.find('.rate').val());
        inkg = parseFloat(tr.find('.cartonid').find('option:selected').attr('data-inkg'));
        qty = parseFloat(tr.find('.qty').val());
        ratetype = tr.find('.ratetype').val();
        cartonid = tr.find('.cartonid').val();
        carton = tr.find('.cartonid').find('option:selected').text();
        if(isNumber(rate) && isNumber(qty)){
            kg = getDecimal(inkg * qty);
            tr.find('.kg').val(kg);
            switch(ratetype){
                case 'KG':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.KG));
                    break;
                case 'GM':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.GM));
                    break;
                case 'LB':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.LB));
                    break;
                case 'BLOCK':
                case 'PACKET':
                    price = getDecimal(qty * rate * parseInt(carton.split('X')[0]));
                    break;
                case 'CARTON':
                    price = getDecimal(qty * rate);
                    break;
            }
            // price = price.toFixed(3);
            // kg = kg.toFixed(3);

            tr.find('.price').val(price);
            totalprice += price;
            totalkg += kg;
            totalqty += qty;
        }
    });

    $( 'table.grid-carton #totalqty' ).html(bdt_format(totalqty));
    $( 'table.grid-carton #totalkg' ).html(bdt_format(totalkg,3));
    $( 'table.grid-carton #totalprice' ).html(bdt_format(totalprice,2));
}



function calculateShrimpBlock()
{
    var blockid, block, tr, ratetype, rate = kg = inkg = qty = price = totalkg = totalprice = totalqty = 0;
    $( 'table.grid-block tbody tr' ).each(function() {
        tr = $(this);
        rate = parseFloat(tr.find('.rate').val());
        inkg = parseFloat(tr.find('.blockid').find('option:selected').attr('data-inkg'));
        qty = parseFloat(tr.find('.qty').val());
        ratetype = tr.find('.ratetype').val();
        blockid = tr.find('.blockid').val();
        block = tr.find('.blockid').find('option:selected').text();
        if(isNumber(rate) && isNumber(qty)){
            kg = getDecimal(inkg * qty);
            tr.find('.kg').val(kg);
            switch(ratetype){
                case 'KG':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.KG));
                    break;
                case 'GM':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.GM));
                    break;
                case 'LB':
                    price = getDecimal((rate * kg) / parseFloat(unitarr.LB));
                    break;
                case 'BLOCK':
                case 'PACKET':
                    price = getDecimal(qty * rate * parseInt(block.split(' ')[0]));
                    break;
            }

            tr.find('.price').val(price);
            totalprice += price;
            totalkg += kg;
            totalqty += qty;
        }
    });

    $( 'table.grid-block #totalqty' ).html(bdt_format(totalqty));
    $( 'table.grid-block #totalkg' ).html(bdt_format(totalkg,3));
    $( 'table.grid-block #totalprice' ).html(bdt_format(totalprice,2));
}
